#include "cpu/menon2007_cpu.hpp"
#include <new>

extern "C" void* isa_create(int variant) {
    if (variant==1 && !__builtin_cpu_supports("avx2")) return nullptr;
    if (variant==2 && !(__builtin_cpu_supports("avx512f") &&
        __builtin_cpu_supports("avx512bw") && __builtin_cpu_supports("avx512vl"))) return nullptr;
    return new (std::nothrow) menon2007_cpu::Workspace;
}
extern "C" void isa_destroy(void* context) {
    delete static_cast<menon2007_cpu::Workspace*>(context);
}
extern "C" void isa_process(void* context,const uint8_t* raw,uint8_t* bgr,
        int width,int height,int pattern,int variant) {
    auto& workspace=*static_cast<menon2007_cpu::Workspace*>(context);
    if (variant==0) menon2007_cpu::scalar_rows(workspace,raw,width,bgr,width*3,width,height,pattern==1,0,height);
    if (variant==1) menon2007_cpu::avx2_rows(workspace,raw,width,bgr,width*3,width,height,pattern==1,0,height);
    if (variant==2) menon2007_cpu::avx512_rows(workspace,raw,width,bgr,width*3,width,height,pattern==1,0,height);
}
